import java.util.Scanner;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        long n = sc.nextLong();
        long[] costs = new long[3];
        costs[0] = sc.nextLong();
        costs[1] = sc.nextLong();
        costs[2] = sc.nextLong();

        Arrays.sort(costs);

        int count = 0;
        long sum = 0;

        for (int i = 0; i < 3; i++) {
            if (sum + costs[i] <= n) {
                sum += costs[i];
                count++;
            } else {
                break;
            }
        }

        System.out.println(count);
    }
}
